/**
 * Design and operating ranges of every pyro-line monitoring point —
 * OSW-PE-SNL-PYR-01 Rev. 01 "Pyro-Line Sensor List, machine-wise register with
 * design and operating ranges" (19 Oct 2026, design review, for site
 * verification). Generated from the document; the text fields are as printed.
 *
 * design   instrument (transmitter) range, LRV – URV
 * nominal  normal operating value or band at design throughput
 * LL / L   second / first low set-point  (trip or interlock / alarm to operator)
 * H / HH   first / second high set-point (alarm to operator / trip or interlock)
 * For draft (negative pressure) H means less negative than nominal. "–" = not used.
 *
 * Numbers (designLo … hh) are in the document's unit; `conv` says how they map
 * onto our signal's unit (see `./limits` applyRangeLimits):
 *   same  same unit · mmwg  mmWG → mbar (÷ 10.197) · barg  bar(g) → mbar (× 1000)
 *   pct   % of a rating (FLA, rated speed or power, design flow): 100 % is taken
 *         from our signal's normal value at the middle of the nominal band until
 *         the nameplate / design figure is confirmed
 *   none  digital, lab, deviation-based or % bin rows: the text only
 * STS-KLN-08's row ("°C shell max") applies to the shell map maximum CAL-KLN-03.
 *
 * Pure data, no React and no server imports.
 */

export interface PyroRangeRow {
  tag: string;
  /** Signal whose numbers this row sets, when not `tag` itself. */
  appliesTo?: string;
  docUnit: string;
  design: string;
  nominal: string;
  LL: string;
  L: string;
  H: string;
  HH: string;
  status: string | null;
  remarks: string;
  conv: "same" | "mmwg" | "barg" | "pct" | "none";
  designLo: number | null;
  designHi: number | null;
  nominalLo: number | null;
  nominalHi: number | null;
  ll: number | null;
  l: number | null;
  h: number | null;
  hh: number | null;
}

